interface ImportJob { id: string; status: string; added: number; updated: number; skipped: number; errors: number; current_path: string; error_note: string; created_at: string }
const me = ref<Employee | null>(null)
const scanMode=ref('immediate')
const company = ref('公司资源库'), smsEnabled = ref(false), initialLoading = ref(true)
const companyShortName = ref('公司资源库'), logoURL = ref(''), copyright = ref('长沙感梦科技有限公司 版权所有'), copyrightURL = ref('https://www.gmkj.cc/'), defaultTheme = ref('explorer'), themePreference = ref('default')
const themeOptions = [{ id:'explorer',name:'目录工作台' },{ id:'library',name:'影像资料库' },{ id:'classic',name:'清爽协作' }]
const theme = computed(() => themePreference.value === 'default' ? defaultTheme.value : themePreference.value)
const companyRecursive = ref(false), companyBrowser = ref<InstanceType<typeof CompanyBrowser>>()
const loginMode = ref('password'), account = ref(''), password = ref(''), mobile = ref(''), code = ref(''), loginBusy = ref(false), smsBusy = ref(false), cooldown = ref(0)
const nav = ref('files'), scope = ref('company'), parent = ref(''), search = ref(''), type = ref(''), sort = ref('updated'), page = ref(1), total = ref(0), view = ref('list'), loading = ref(false)
const resources = ref<Resource[]>([]), ancestors = ref<{ id: string; name: string }[]>([]), stats = ref<Record<string, any>>({})
const detail = ref<Resource | null>(null), detailOpen = ref(false), previewOpen = ref(false)
const editOpen = ref(false), editing = ref<Resource | null>(null), editForm = ref({ name: '', remark: '' }), saving = ref(false)
const folderOpen = ref(false), folderForm = ref({ name: '', remark: '' })
const uploadOpen = ref(false), uploadDrawer = ref(false), selections = ref<{ file: File; remark: string; relativePath?: string }[]>([]), tasks = ref<UploadTask[]>([]), uploadRunning = ref(false)
const directoryInput = ref<HTMLInputElement>()
const selected = ref<Resource[]>([]), batchBusy = ref(false)
const resourceTable = ref<{ clearSelection: () => void }>()
const sameSelectedDirectory = computed(() => selected.value.length > 0 && selected.value.every(f => f.parent_id === selected.value[0]?.parent_id && f.scope === selected.value[0]?.scope))
const canBatchTrash = computed(() => sameSelectedDirectory.value && selected.value.every(f => f.can_manage && !f.deleted))
const canBatchDownload = computed(() => sameSelectedDirectory.value && selected.value.every(f => f.kind === 'file' && canDownload(f)))
const folderLimits = ref({ max_files:0,max_entries:0,max_depth:0,max_bytes:0 }), folderDownloadBusy = ref('')
const browseOwner = ref(''), browseDept = ref(''), storageStatus = ref<Record<string, any> | null>(null)
const fileInput = ref<HTMLInputElement>(), resumeInput = ref<HTMLInputElement>(), resumeTarget = ref<UploadTask | null>(null), uploadAbort = shallowRef<AbortController | null>(null)
const users = ref<Employee[]>([]), departments = ref<{ id: string; name: string; parent_id: string }[]>([]), userSearch = ref(''), userOpen = ref(false), editingUser = ref<Employee | null>(null)
const userForm = ref({ username: '', display_name: '', mobile: '', password: '', role: 'member', dept_id: '', enabled: true, quota_gb: 20 })
const deptOpen = ref(false), deptForm = ref({ name: '', parent_id: '' }), system = ref<Record<string, any>>({}), jobs = ref<ImportJob[]>([]), logs = ref<any[]>([]), importBusy = ref(false)
const passwordOpen = ref(false), passwordForm = ref({ old_password: '', new_password: '', confirm: '' })
const titles: Record<string, string> = { company: '公司空间', department: '部门空间', personal: '个人空间' }
