const scanNames: Record<string, string> = { pending: '待安全检查', scanning: '安全检查中', clean: '已通过检查', infected: '已阻止访问', failed: '检查失败' }
const jobNames: Record<string, string> = { running: '扫描中', completed: '已完成', interrupted: '已中断', failed: '失败', partial: '部分完成' }
const actionNames: Record<string, string> = { login: '登录', sms_send: '发送登录验证码', password_change: '修改密码', local_admin_password_reset: '本机重置超管密码', user_create: '新增员工', user_update: '调整员工账号', department_create: '新增部门', upload_init: '开始上传', upload_complete: '上传完成', upload_cancel: '取消上传', file_edit: '编辑名称或备注', folder_create: '新建目录', file_trash: '移入回收站', file_restore: '恢复文件', file_content: '访问文件内容', file_batch_trash:'批量移入回收站',file_batch_archive_prepare:'准备批量文件下载',file_batch_archive_download:'批量下载文件',folder_archive_prepare:'准备目录下载',folder_archive_download:'下载目录 ZIP', file_review: '审核文件', import_start: '开始扫描资料', import_finish: '资料扫描结束', file_scan: '文件安全检查', storage_unify:'统一文件目录', scan_retry: '重试安全检查', site_settings_update:'修改站点配置', site_listen_port_update:'修改监听端口', site_restart:'重启站点',scan_settings_update:'修改病毒检查策略', site_logo_update:'修改公司 Logo', sms_settings_update:'修改短信配置' }
const pageTitle = computed(() => nav.value === 'files' ? titles[scope.value] : ({ trash: '回收站', review: '发布审核', users: '人员与部门', imports: '公司资料扫描', audit: '操作日志', settings:'站点配置' }[nav.value] || '资源管理'))
const scopeDescription = computed(() => scope.value === 'company' ? '共享公司资料，让每一份资源有序流转。' : scope.value === 'department' ? `${departments.value.find(d => d.id === (browseDept.value || me.value?.dept_id))?.name || '请选择部门'}成员共享的工作资料。` : `${users.value.find(u => u.id === browseOwner.value)?.display_name || '本人'}的个人文件，本人及超管、维护管理员可见。`)
const isSuperAdmin = computed(() => me.value?.role === 'admin')
const isAdmin = computed(() => ['admin','maintainer'].includes(me.value?.role || ''))
const assignableRoles = computed(() => Object.fromEntries(Object.entries(roleNames).filter(([key]) => isSuperAdmin.value || key !== 'admin')) )
const canReview = computed(() => isAdmin.value || me.value?.role === 'dept_admin')
const visibleUsers = computed(() => users.value.filter(u => `${u.display_name} ${u.username} ${u.mobile}`.includes(userSearch.value)))
const quotaPercent = computed(() => Math.min(100, Math.round((stats.value.personal_used || 0) / (stats.value.personal_quota || 1) * 100)))
const activeJob = computed(() => jobs.value.find(j => j.status === 'running'))
const contentURL = computed(() => detail.value ? `/api/files/${detail.value.id}/content?preview=true` : '')
const previewKind = computed(() => { const m = detail.value?.mime || ''; if (['image/jpeg','image/png','image/gif','image/webp','image/avif','image/bmp'].includes(m)) return 'image'; if (['video/mp4','video/webm'].includes(m)) return 'video'; if (['audio/mpeg','audio/wav','audio/ogg','audio/mp4'].includes(m)) return 'audio'; if (m === 'application/pdf') return 'pdf'; return '' })
let storagePoll: ReturnType<typeof setInterval> | undefined
let poll: ReturnType<typeof setInterval> | undefined, debounce: ReturnType<typeof setTimeout> | undefined, requestVersion = 0

async function api<T = any>(path: string, method = 'GET', body?: any, signal?: AbortSignal): Promise<T> {
  const headers: Record<string, string> = {}
  if (me.value?.csrf) headers['X-CSRF-Token'] = me.value.csrf
  let payload: BodyInit | undefined
  if (body instanceof Blob) payload = body
  else if (body !== undefined) { headers['Content-Type'] = 'application/json'; payload = JSON.stringify(body) }
  const response = await fetch(`/api${path}`, { method, headers, body: payload, credentials: 'same-origin', signal })
  const result = await response.json().catch(() => ({}))
  if (!response.ok) { if (response.status === 401 && !path.startsWith('/auth/')) me.value = null; throw new Error(result.error || '操作失败，请重试') }
  return result as T
}
function report(error: any) { if (error?.name !== 'AbortError' && error !== 'cancel' && error !== 'close') ElMessage.error(error?.message || '操作未完成') }
function size(n: number) { if (!n) return '0 B'; const units = ['B','KB','MB','GB','TB']; const i = Math.min(Math.floor(Math.log(n) / Math.log(1024)), 4); return `${(n / 1024 ** i).toFixed(i > 1 ? 1 : 0)} ${units[i]}` }
function date(s: string) { return new Date(s).toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
function icon(f: Resource) { return f.kind === 'folder' ? Folder : f.mime.startsWith('image/') ? Picture : f.mime.startsWith('video/') ? VideoCamera : f.mime.startsWith('audio/') ? Headset : /\.(zip|rar|7z|exe|msi)$/i.test(f.name) ? Box : Document }
function fileClass(f: Resource) { return f.kind === 'folder' ? 'folder' : f.mime.startsWith('image/') ? 'image' : f.mime.startsWith('video/') ? 'video' : /\.(pdf)$/i.test(f.name) ? 'pdf' : 'document' }
function imagePreviewable(f: Resource) { return ['image/jpeg','image/png','image/gif','image/webp','image/avif','image/bmp'].includes(f.mime) }
function canDownload(f: Resource) { return f.can_download }
function statusText(f: Resource) { if(f.source_missing)return '源文件缺失';if(f.kind==='folder')return '文件夹';const publication=f.publication==='pending'?'待发布审核':f.publication==='rejected'?'审核未通过':'';return [publication,f.scan_warning?'未执行病毒检查':scanNames[f.scan_status]||f.scan_status].filter(Boolean).join(' · ') }

async function login() {
  if (loginMode.value === 'password' ? !account.value.trim() || !password.value : !mobile.value || !code.value) { ElMessage.warning('请填写完整登录信息'); return }
  loginBusy.value = true
  try { me.value = loginMode.value === 'password' ? await api('/auth/login','POST',{ account: account.value.trim(), password: password.value }) : await api('/auth/sms/login','POST',{ mobile: mobile.value, code: code.value }); password.value = ''; code.value = ''; await loadWorkspace(); ElMessage.success('登录成功') } catch (e) { report(e) } finally { loginBusy.value = false }
}
async function sendCode() { if (!/^1[3-9]\d{9}$/.test(mobile.value)) { ElMessage.warning('请输入有效手机号'); return }; smsBusy.value = true; try { const result = await api('/auth/sms/send','POST',{ mobile: mobile.value }); cooldown.value = result.cooldown_seconds; ElMessage.success(result.message) } catch (e) { report(e) } finally { smsBusy.value = false } }
async function logout() { try { uploadAbort.value?.abort(); await api('/auth/logout','POST'); me.value = null; resources.value = []; detailOpen.value = false; nav.value = 'files'; scope.value = 'company' } catch (e) { report(e) } }
async function loadWorkspace() { await Promise.all([loadFiles(), refreshStats(), loadTasks(), loadDepartments(),loadStorageStatus(),...(isAdmin.value ? [loadManagedUsers()] : [])]) }
async function refreshStats() { stats.value = await api(`/stats?${new URLSearchParams({owner:scope.value === 'personal' ? browseOwner.value : '',dept:scope.value === 'department' ? browseDept.value : ''})}`) }
async function loadPublicConfig() { const conf = await api('/public-config'); scanMode.value=conf.virus_scan_mode || 'immediate'; company.value = conf.company_name; companyShortName.value = conf.company_short_name; logoURL.value = conf.logo_url; copyright.value = conf.copyright; copyrightURL.value = conf.copyright_url; defaultTheme.value = conf.default_theme; smsEnabled.value = conf.sms_enabled; folderLimits.value = conf.folder_transfer_limits; document.title = `${company.value} · 文件资源管理` }
function rememberTheme() { try { if (me.value) localStorage.setItem(`gmpan-theme:${me.value.id}`,themePreference.value) } catch {} }
watch(theme, value => { document.documentElement.dataset.theme = value; selected.value = []; view.value = value === 'library' ? 'grid' : 'list' }, { immediate: true })
watch(view, () => { selected.value = [] })
watch(selected, value => { if (!value.length) { resourceTable.value?.clearSelection(); companyBrowser.value?.clearSelection() } })
watch(() => me.value?.id, id => { let saved = 'default'; try { if (id) saved = localStorage.getItem(`gmpan-theme:${id}`) || 'default' } catch {}; themePreference.value = ['default',...themeOptions.map(t=>t.id)].includes(saved) ? saved : 'default' })
async function previewFile(f: Resource) { try { detail.value = await api(`/files/${f.id}`); detailOpen.value = false; previewOpen.value = true } catch (e) { report(e) } }
async function loadDepartments() { departments.value = await api('/departments') }
async function siteUpdated() { await Promise.all([loadPublicConfig(),loadStorageStatus()]) }
async function loadManagedUsers() { users.value = await api('/admin/users') }
async function loadStorageStatus() { storageStatus.value = await api('/storage-status') }
function uploadTarget() { return { scope:scope.value, owner_id:isAdmin.value && scope.value === 'personal' ? browseOwner.value : '', dept_id:isAdmin.value && scope.value === 'department' ? browseDept.value : '' } }
async function targetChanged() { parent.value = ''; search.value = ''; page.value = 1; detailOpen.value = false; await Promise.all([loadFiles(),refreshStats()]) }
async function loadFiles() {
  const version = ++requestVersion; loading.value = true; selected.value = []
  try { const p = new URLSearchParams({ scope: scope.value, parent: parent.value, q: search.value, type: type.value, sort: sort.value, page: String(page.value), trash: String(nav.value === 'trash'), review: String(nav.value === 'review'), directory:String(scope.value === 'company' && nav.value === 'files'), recursive:String(companyRecursive.value),owner:scope.value === 'personal' ? browseOwner.value : '',dept:scope.value === 'department' ? browseDept.value : '' }); const result = await api(`/files?${p}`); if (version !== requestVersion) return; resources.value = result.items; total.value = result.total; ancestors.value = result.ancestors } catch (e) { report(e) } finally { if (version === requestVersion) loading.value = false }
}
async function navigate(next: string, nextScope?: string) {
  nav.value = next; browseOwner.value = ''; browseDept.value = ''; if (nextScope) scope.value = nextScope; parent.value = ''; search.value = ''; type.value = ''; page.value = 1; detailOpen.value = false
  try { if (['files','trash','review'].includes(next)) await Promise.all([loadFiles(),refreshStats()]); if (next === 'users') { users.value = await api('/admin/users'); await loadDepartments() }; if (next === 'imports') await loadImports(); if (next === 'audit') logs.value = await api('/admin/audit') } catch (e) { report(e) }
}
function searchChanged() { clearTimeout(debounce); debounce = setTimeout(() => { page.value = 1; void loadFiles() }, 350) }
function filterChanged() { page.value = 1; void loadFiles() }
async function openFolder(id = '') { parent.value = id; page.value = 1; search.value = ''; await loadFiles() }
async function showDetails(f: Resource) { try { detail.value = await api(`/files/${f.id}`); detailOpen.value = true } catch(e) {report(e)} }
async function openFile(f: Resource) { try { if (f.kind === 'folder' && nav.value === 'files') { await openFolder(f.id); return }; if (imagePreviewable(f) && canDownload(f)) { await previewFile(f); return }; detail.value = await api(`/files/${f.id}`); detailOpen.value = true } catch (e) { report(e) } }
async function download(f: Resource) { if (f.kind === 'folder') { await downloadFolder(f); return }; if (!canDownload(f)) { ElMessage.warning('文件需通过安全检查后才可下载'); return }; const a = document.createElement('a'); a.href = `/api/files/${f.id}/content`; a.download = f.name; a.click() }
async function batchTrash() {
  if (!canBatchTrash.value || batchBusy.value) return
  const ids = selected.value.map(f => f.id)
  try { await ElMessageBox.confirm(`将选中的 ${ids.length} 个项目移入回收站？目录内子项一并处理，原文件保留，可从回收站恢复。`,'批量移入回收站',{confirmButtonText:'移入回收站',cancelButtonText:'取消',type:'warning'}); batchBusy.value = true; const result = await api('/files/batch-trash','POST',{ids}); await Promise.all([loadFiles(),refreshStats()]); companyBrowser.value?.refreshTree(); ElMessage.success(`已移入回收站，共 ${result.count} 个项目（含子项）`) } catch(e) {report(e)} finally {batchBusy.value = false}
}
async function batchDownload() {
  if (!canBatchDownload.value || batchBusy.value || folderDownloadBusy.value) return
  batchBusy.value = true
  const message = ElMessage({message:'正在准备所选文件 ZIP…',duration:0})
  try {const result = await api('/files/batch-download','POST',{ids:selected.value.map(f => f.id)}); const a = document.createElement('a'); a.href = result.url; a.download = result.name; a.click(); ElMessage.success('所选文件 ZIP 已准备，浏览器开始下载')} catch(e) {report(e)} finally {message.close();batchBusy.value = false}
}
function toggleSelected(f: Resource,value:boolean) { selected.value = value ? [...selected.value.filter(item => item.id !== f.id),f] : selected.value.filter(item => item.id !== f.id) }
async function downloadFolder(f: Resource) {
  if (folderDownloadBusy.value || batchBusy.value) { ElMessage.warning('目录正在打包，请稍候'); return }
  folderDownloadBusy.value = f.id
  const message = ElMessage({message:'正在准备目录 ZIP，请稍候…',duration:0})
  try { const result = await api(`/folders/${f.id}/download`,'POST'); const a = document.createElement('a'); a.href = result.url; a.download = result.name; a.click(); ElMessage.success('ZIP 已准备，浏览器开始下载') } catch (e) {report(e)} finally {message.close();folderDownloadBusy.value = ''}
}
function startEdit(f: Resource) { editing.value = f; editForm.value = { name: f.name, remark: f.remark }; editOpen.value = true }
async function saveEdit() { if (!editing.value) return; saving.value = true; try { await api(`/files/${editing.value.id}`,'PATCH',editForm.value); editOpen.value = false; if (detail.value?.id === editing.value.id) detail.value = await api(`/files/${editing.value.id}`); await loadFiles(); ElMessage.success('名称和备注已保存') } catch (e) { report(e) } finally { saving.value = false } }
async function createFolder() { saving.value = true; try { await api('/folders','POST',{ ...folderForm.value, ...uploadTarget(), parent_id: parent.value }); folderOpen.value = false; folderForm.value = { name: '', remark: '' }; await loadFiles(); companyBrowser.value?.refreshTree(); ElMessage.success('文件夹已创建') } catch (e) { report(e) } finally { saving.value = false } }
async function trash(f: Resource) { try { await ElMessageBox.confirm(`将“${f.name}”移入回收站？文件夹内项目会一并处理，磁盘原文件不会被删除。`, '移入回收站', { confirmButtonText: '移入回收站', cancelButtonText: '取消', type: 'warning' }); await api(`/files/${f.id}/trash`,'POST'); detailOpen.value = false; await Promise.all([loadFiles(),refreshStats()]); companyBrowser.value?.refreshTree(); ElMessage.success('已移入回收站') } catch (e) { report(e) } }
async function restore(f: Resource) { try { await api(`/files/${f.id}/restore`,'POST'); detailOpen.value = false; await Promise.all([loadFiles(),refreshStats()]); ElMessage.success('已恢复') } catch (e) { report(e) } }
async function review(f: Resource, approve: boolean) { try { await api(`/files/${f.id}/approve`,'POST',{ approve }); await loadFiles(); ElMessage.success(approve ? '已发布' : '已退回') } catch (e) { report(e) } }
async function copyLink(f: Resource) { try { const text = `${location.origin}/?file=${encodeURIComponent(f.id)}`; if (navigator.clipboard) { await navigator.clipboard.writeText(text); ElMessage.success('内部链接已复制，接收人仍需具有文件权限') } else { await ElMessageBox.alert(text, '内部文件链接', { confirmButtonText: '关闭' }) } } catch (e) { report(e) } }
function menuAction(command: string, f: Resource) { if (command === 'edit') startEdit(f); else if (command === 'trash') void trash(f); else if (command === 'link') void copyLink(f); else if (command === 'download') void download(f); else if (command === 'preview') void previewFile(f); else if (command === 'details') void showDetails(f) }

function addFiles(list: FileList | null) { if (!list) return; for (const file of Array.from(list)) selections.value.push({ file, remark: '' }); if (fileInput.value) fileInput.value.value = '' }
function validateDirectorySelection(files: {file:File;relativePath?:string}[]) {
  const folders = new Set<string>(); let bytes = 0
  for (const item of files) {
    bytes += item.file.size
    const parts = (item.relativePath || '').split('/').slice(0,-1)
    if (parts.length > folderLimits.value.max_depth) throw new Error(`目录最多 ${folderLimits.value.max_depth} 层，请分批上传`)
    for (let i = 1;i <= parts.length;i++) folders.add(parts.slice(0,i).join('/'))
  }
  if (files.length > folderLimits.value.max_files || bytes > folderLimits.value.max_bytes || files.length + folders.size > folderLimits.value.max_entries) throw new Error(`目录上传每次最多 ${folderLimits.value.max_files} 个文件、${size(folderLimits.value.max_bytes)}、${folderLimits.value.max_entries} 个文件及目录，请分批选择`)
}
function addDirectory(list: FileList | null) { if (!list) return; try { const files = Array.from(list).map(file => ({file,remark:'',relativePath:file.webkitRelativePath})); validateDirectorySelection([...selections.value,...files]); selections.value.push(...files) } catch(e) {report(e)} finally {if(directoryInput.value) directoryInput.value.value = ''} }
function dropFiles(e: DragEvent) { e.preventDefault(); addFiles(e.dataTransfer?.files || null) }
async function loadTasks() { const pending: UploadTask[] = await api('/uploads'); tasks.value = pending.map(t => ({ ...t, ...tasks.value.find(old => old.id === t.id) })) }
async function beginUpload() {
  if (!selections.value.length) return; if (selections.value.some(f => f.relativePath)) {try {validateDirectorySelection(selections.value)} catch(e) {report(e);return}}; const selected = selections.value.slice(); const destination = { ...uploadTarget(), parent_id: parent.value }; selections.value = []; uploadOpen.value = false; uploadDrawer.value = true
  const folderIDs = new Map<string,string>()
  try {
    for (const selectedFile of selected) {
      const parts = (selectedFile.relativePath || '').split('/').slice(0,-1)
      let parentID = destination.parent_id, relative = ''
      for (const name of parts) {
        if (!name || name === '.' || name === '..') throw new Error('文件夹路径不正确')
        relative += '/' + name
        if (!folderIDs.has(relative)) { const folder = await api('/folders','POST',{ ...destination,parent_id:parentID,name,remark:'' }); folderIDs.set(relative,folder.id) }
        parentID = folderIDs.get(relative)!
      }
    }
  } catch (e) { selections.value = selected; report(e); await loadFiles(); companyBrowser.value?.refreshTree(); return }
  for (const selectedFile of selected) { try { const parentPath = (selectedFile.relativePath || '').split('/').slice(0,-1).join('/'); const targetParent = parentPath ? folderIDs.get('/'+parentPath)! : destination.parent_id; const init = await api('/uploads','POST',{ ...destination,parent_id:targetParent, name: selectedFile.file.name, remark: selectedFile.remark, size: selectedFile.file.size }); const task = reactive<UploadTask>({ ...init, name: selectedFile.file.name, remark: selectedFile.remark, size: selectedFile.file.size, ...destination, parent_id:targetParent, progress: 0, state: '等待上传' }); tasks.value.unshift(task); await transfer(task,selectedFile.file) } catch (e) { report(e) } }
  await Promise.all([loadFiles(),refreshStats()]); companyBrowser.value?.refreshTree()
}
async function sha(blob: Blob) { const hash = await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()); return Array.from(new Uint8Array(hash),b => b.toString(16).padStart(2,'0')).join('') }
async function transfer(task: UploadTask,file: File) {
  const controller = new AbortController(); uploadAbort.value = controller; uploadRunning.value = true; task.error = ''; task.state = '核对上传进度'
  try {
    const status: UploadTask = await api(`/uploads/${task.id}`); const done = new Set(status.chunks || []); const chunk = 5 * 1024 * 1024
    for (const i of done) { if (controller.signal.aborted) throw new DOMException('已暂停','AbortError'); if (status.chunk_hashes?.[String(i)] && await sha(file.slice(i * chunk,Math.min((i+1)*chunk,file.size))) !== status.chunk_hashes[String(i)]) throw new Error('所选文件与已上传分片不一致，请选择原文件或取消后重新上传') }
    task.progress = Math.round(done.size / task.total_chunks * 100); task.state = '上传中'; const remaining = Array.from({ length: task.total_chunks },(_,i) => i).filter(i => !done.has(i)); let cursor = 0
    await Promise.all(Array.from({ length: Math.min(3,remaining.length) },async () => { while (cursor < remaining.length) { const i = remaining[cursor++]!; await api(`/uploads/${task.id}/chunks/${i}`,'PUT',file.slice(i*chunk,Math.min((i+1)*chunk,file.size)),controller.signal); done.add(i); task.progress = Math.round(done.size/task.total_chunks*100) } }))
    if (controller.signal.aborted) throw new DOMException('已暂停','AbortError'); task.state = '正在合并'; await api(`/uploads/${task.id}/complete`,'POST'); task.state = '上传完成，等待安全检查'; task.progress = 100; ElMessage.success(`${task.name} 已上传`)
  } catch (e: any) { task.state = e?.name === 'AbortError' ? '已暂停，可续传' : '上传未完成'; task.error = e?.name === 'AbortError' ? '' : e.message; controller.abort() } finally { uploadRunning.value = false; uploadAbort.value = null; tasks.value = [...tasks.value] }
}
function selectResume(t: UploadTask) { resumeTarget.value = t; resumeInput.value?.click() }
async function resumeSelected(e: Event) { const input = e.target as HTMLInputElement; const file = input.files?.[0]; const task = resumeTarget.value; input.value = ''; if (!file || !task) return; if (file.name !== task.name || file.size !== task.size) { ElMessage.error('请选择同名、同大小的原文件'); return }; await transfer(task,file); await Promise.all([loadFiles(),refreshStats()]) }
async function cancelTask(t: UploadTask) { try { await api(`/uploads/${t.id}`,'DELETE'); tasks.value = tasks.value.filter(x => x.id !== t.id) } catch (e) { report(e) } }
function showUser(u?: Employee) { editingUser.value = u || null; userForm.value = u ? { username:u.username, display_name:u.display_name, mobile:u.mobile, password:'', role:u.role, dept_id:u.dept_id, enabled:u.enabled, quota_gb:u.quota_bytes/1024**3 } : { username:'',display_name:'',mobile:'',password:'',role:'member',dept_id:'',enabled:true,quota_gb:20 }; userOpen.value = true }
async function saveUser() { saving.value = true; try { const { quota_gb,...rest } = userForm.value; await api(editingUser.value ? `/admin/users/${editingUser.value.id}` : '/admin/users',editingUser.value ? 'PATCH':'POST',{ ...rest,quota_bytes:Math.round(quota_gb*1024**3) }); userOpen.value = false; ElMessage.success('员工信息已保存'); if (editingUser.value?.id === me.value?.id) { me.value = null; return }; users.value = await api('/admin/users') } catch (e) { report(e) } finally { saving.value = false } }
async function createDepartment() { saving.value = true; try { await api('/admin/departments','POST',deptForm.value); deptOpen.value = false; deptForm.value = { name:'',parent_id:'' }; await loadDepartments(); ElMessage.success('部门已创建') } catch (e) { report(e) } finally { saving.value = false } }
async function loadImports() { [system.value,jobs.value] = await Promise.all([api('/admin/system'),api('/admin/imports')]) }
async function startImport() { try { await ElMessageBox.confirm('扫描指定历史资料目录，按原目录层级登记到公司空间。新登记文件对全员可见，不搬动或删除源文件，已有备注保持不变。','扫描历史资料',{ confirmButtonText:'开始扫描',cancelButtonText:'取消' }); importBusy.value = true; await api('/admin/imports','POST'); await loadImports(); ElMessage.success('扫描任务已启动') } catch (e) { report(e) } finally { importBusy.value = false } }
async function retryScans() { try { const result = await api('/admin/scans/retry','POST'); ElMessage.success(`${result.count} 个文件已重新排队`); await loadImports() } catch (e) { report(e) } }
async function changePassword() { if (passwordForm.value.new_password !== passwordForm.value.confirm) { ElMessage.warning('两次新密码不一致'); return }; saving.value = true; try { await api('/auth/password','POST',{ old_password:passwordForm.value.old_password,new_password:passwordForm.value.new_password }); passwordOpen.value = false; passwordForm.value = { old_password:'',new_password:'',confirm:'' }; me.value = null; ElMessage.success('密码已修改，请重新登录') } catch (e) { report(e) } finally { saving.value = false } }
onMounted(async () => {
  try { await loadPublicConfig(); try { me.value = await api('/me'); await loadWorkspace(); const id = new URLSearchParams(location.search).get('file'); if (id) { detail.value = await api(`/files/${id}`); detailOpen.value = true } } catch (e) { if (me.value) report(e) } } catch (e) { report(e) } finally { initialLoading.value = false }
  storagePoll = setInterval(() => {if (me.value && !document.hidden) void loadStorageStatus().catch(report)},60000)
  poll = setInterval(() => { if (cooldown.value > 0) cooldown.value--; if (!me.value || document.hidden) return; if (nav.value === 'imports' && activeJob.value) void loadImports().catch(report) },1000)
})
onUnmounted(() => { clearInterval(poll); clearInterval(storagePoll); clearTimeout(debounce); uploadAbort.value?.abort() })
</script>

<template>
