    <section class="login-form"><div class="login-box"><span class="welcome-label">欢迎回来</span><h2>登录公司资源库</h2><p>使用管理员为你开通的员工账号</p><el-tabs v-model="loginMode"><el-tab-pane label="账号密码登录" name="password" /><el-tab-pane label="短信验证码登录" name="sms" :disabled="!smsEnabled" /></el-tabs><el-form label-position="top" @submit.prevent="login"><template v-if="loginMode === 'password'"><el-form-item label="用户名 / 手机号"><el-input v-model="account" size="large" placeholder="请输入用户名或已绑定手机号" autocomplete="username" :prefix-icon="User" /></el-form-item><el-form-item label="密码"><el-input v-model="password" size="large" type="password" show-password autocomplete="current-password" placeholder="请输入密码" :prefix-icon="Lock" /></el-form-item></template><template v-else><el-form-item label="手机号"><el-input v-model="mobile" size="large" inputmode="tel" maxlength="11" placeholder="请输入已绑定手机号" autocomplete="tel" /></el-form-item><el-form-item label="验证码"><div class="code-row"><el-input v-model="code" size="large" inputmode="numeric" autocomplete="one-time-code" placeholder="请输入验证码" /><el-button size="large" :loading="smsBusy" :disabled="cooldown > 0" @click="sendCode">{{ cooldown ? `${cooldown} 秒后重试` : '获取验证码' }}</el-button></div></el-form-item></template><el-button native-type="submit" class="login-submit" type="primary" size="large" :loading="loginBusy">登录<el-icon><ArrowRight /></el-icon></el-button></el-form><div class="login-help"><el-icon><CircleCheck /></el-icon> 仅限已开通账号的公司员工使用</div><p v-if="!smsEnabled" class="subtle">短信登录尚未启用，可使用账号密码登录。</p><div class="login-contact">账号开通或密码重置，请联系公司管理员</div><div class="login-copyright"><a :href="copyrightURL" target="_blank" rel="noopener noreferrer">© {{ copyright }}</a></div></div></section>
  </main>
  <div v-else class="app-shell">
