t="false" :stroke-width="4" color="#4ea98e" /><p>{{ size(stats.personal_used || 0) }} / {{ size(stats.personal_quota || me.quota_bytes) }}</p><div class="private-tip"><el-icon><Lock /></el-icon><span>本人及管理员可访问个人文件</span></div></div></aside>
    <div class="main-shell"><header class="topbar"><div class="topbar-location">工作空间<el-icon><ArrowRight /></el-icon><b>{{ pageTitle }}</b></div><div class="topbar-right"><el-select v-model="themePreference" aria-label="界面主题" class="theme-select" @change="rememberTheme"><el-option label="跟随站点默认" value="default"/><el-option v-for="t in themeOptions" :key="t.id" :label="t.name" :value="t.id"/></el-select><el-button class="transfer-button" text :icon="UploadFilled" @click="uploadDrawer = true">传输列表<span v-if="uploadRunning" class="online-dot"></span></el-button><span class="topbar-divider"></span><el-dropdown @command="(c: string) => c === 'logout' ? logout() : passwordOpen = true"><button class="account-button"><span class="avatar">{{ me.display_name.slice(0,1) }}</span><span>{{ me.display_name }}<small>{{ roleNames[me.role] }}</small></span><el-icon><ArrowDown /></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="password" :icon="Setting">修改密码</el-dropdown-item><el-dropdown-item command="logout" divided :icon="SwitchButton">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
      <div class="workspace-content"><el-alert v-if="storageStatus && (!storageStatus.available || storageStatus.low_space)" class="storage-warning" :title="storageStatus.available ? '文件存储空间不足，需要维护' : '无法获取文件存储空间，需要维护检查'" :description="storageStatus.available ? `当前可用 ${size(storageStatus.available_bytes)}，约占 ${Number(storageStatus.available_percent).toFixed(2)}%，低于 ${storageStatus.threshold_percent}% 告警阈值。请联系超管或维护管理员处理。` : '请联系超管或维护管理员检查磁盘、网络目录及服务账号权限。'" type="warning" :closable="false" show-icon/>
        <section class="page-heading"><div><div class="eyebrow">{{ ['files','review','trash'].includes(nav) ? 'RESOURCE LIBRARY' : 'WORKSPACE SETTINGS' }}</div><h1>{{ pageTitle }}<el-tag v-if="nav === 'files'" class="visibility-tag" effect="plain" size="small">{{ scope === 'company' ? '公司全员可见' : scope === 'department' ? '部门成员及管理员可见' : '本人及管理员可见' }}</el-tag></h1><p>{{ nav === 'files' ? scopeDescription : nav === 'imports' ? '登记已有资料，保留目录结构与原文件。' : nav === 'settings' ? '配置公司标识、默认主题、文件目录和短信登录。' : nav === 'users' ? '管理员工账号、部门归属与空间配额。' : nav === 'review' ? '检查并发布员工提交的共享资料。' : nav === 'trash' ? '恢复误删项目；源文件仍保留在磁盘中。' : '查看登录、文件操作与资料导入记录。' }}</p></div><div class="heading-actions" v-if="nav === 'files'"><el-button :icon="Plus" @click="folderOpen = true">新建文件夹</el-button><el-button type="primary" :icon="UploadFilled" @click="uploadOpen = true">上传文件 / 文件夹</el-button></div><div v-if="nav === 'users'" class="heading-actions"><el-button :icon="Plus" @click="deptOpen = true">新增部门</el-button><el-button type="primary" :icon="Plus" @click="showUser()">新增员工</el-button></div></section>
        <template v-if="['files','trash','review'].includes(nav)"><div v-if="isAdmin && scope !== 'company'" class="space-owner-filter"><span>{{ scope === 'personal' ? '个人空间归属' : '部门空间归属' }}</span><el-select v-if="scope === 'personal'" v-model="browseOwner" aria-label="选择员工个人空间" placeholder="我的个人空间" filterable @change="targetChanged"><el-option label="我的个人空间" value=""/><el-option v-for="u in users.filter(u => u.id !== me?.id)" :key="u.id" :value="u.id" :label="`${u.display_name}（${u.username}）`"/></el-select><el-select v-else v-model="browseDept" aria-label="选择部门空间" :placeholder="me.dept_name || '请选择部门'" filterable @change="targetChanged"><el-option :label="me.dept_name || '未指定部门'" value=""/><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></div>
