          <div v-if="nav === 'files'" class="batch-toolbar"><span>已选 {{ selected.length }} 项</span><el-button :disabled="!canBatchDownload || batchBusy || !!folderDownloadBusy" :loading="batchBusy" :icon="Download" @click="batchDownload">批量下载文件</el-button><el-button type="danger" plain :disabled="!canBatchTrash || batchBusy" :loading="batchBusy" :icon="Delete" @click="batchTrash">批量移入回收站</el-button><small>{{ !sameSelectedDirectory && selected.length ? '仅支持同一目录的项目，请调整选择' : selected.some(f => f.kind === 'folder') ? '已选目录：可批量回收；下载请使用单个目录的下载按钮' : '勾选本页项目；批量下载仅支持文件，目录可单独下载' }}</small></div>
          <CompanyBrowser v-if="nav === 'files' && scope === 'company'" ref="companyBrowser" :api="api" :items="resources" :total="total" :page="page" :loading="loading" :parent="parent" :ancestors="ancestors" :search="search" :type="type" :recursive="companyRecursive" :theme="theme" :selected="selected" @select="selected = $event" @trash="trash" @folder="openFolder" @search="search = $event; searchChanged()" @type="type = $event; filterChanged()" @recursive="companyRecursive = $event; filterChanged()" @page="page = $event; loadFiles()" @open="openFile" @download="download" @preview="previewFile" @action="menuAction" @refresh="loadFiles(); refreshStats()"/><section v-else class="files-panel"><div class="file-toolbar"><el-input v-model="search" class="search-input" :prefix-icon="Search" clearable placeholder="搜索文件名或备注…" @input="searchChanged" /><div class="filter-tools"><el-select v-if="nav !== 'files'" v-model="scope" class="scope-select" @change="filterChanged"><el-option v-for="s in ['company','department','personal'].filter(s => nav !== 'review' || s !== 'personal')" :key="s" :label="titles[s]" :value="s" :disabled="s === 'department' && !me.dept_id && !isAdmin" /></el-select><el-select v-model="type" placeholder="全部类型" class="type-select" @change="filterChanged"><el-option label="全部类型" value="" /><el-option label="文件夹" value="folder" /><el-option label="文档" value="document" /><el-option label="图片" value="image" /><el-option label="视频" value="video" /><el-option label="音频" value="audio" /></el-select><el-select v-model="sort" class="sort-select" @change="filterChanged"><el-option label="最近更新" value="updated" /><el-option label="名称排序" value="name" /><el-option label="大小排序" value="size" /></el-select><el-button text :icon="Refresh" title="刷新文件" aria-label="刷新文件" @click="loadFiles(); refreshStats()" /><div class="view-switch"><button :class="{ active:view === 'list' }" title="列表视图" aria-label="列表视图" @click="view = 'list'"><el-icon><List /></el-icon></button><button :class="{ active:view === 'grid' }" title="网格视图" aria-label="网格视图" @click="view = 'grid'"><el-icon><Grid /></el-icon></button></div></div></div><div class="pathbar"><div class="breadcrumbs"><button @click="openFolder()"><el-icon><FolderOpened /></el-icon>{{ titles[scope] }}</button><template v-for="a in ancestors" :key="a.id"><el-icon><ArrowRight /></el-icon><button @click="openFolder(a.id)">{{ a.name }}</button></template><span v-if="search" class="search-result-label">搜索结果</span></div><span>{{ total }} 个项目</span></div>
            <el-table ref="resourceTable" v-if="view === 'list'" v-loading="loading" :data="resources" class="file-table" row-key="id" @selection-change="selected = $event" @row-dblclick="openFile" :empty-text="search ? '没有找到匹配的文件名或备注' : nav === 'review' ? '暂无待审核文件' : nav === 'trash' ? '回收站是空的' : '还没有文件，上传或导入第一份资料吧'"><el-table-column v-if="nav === 'files'" type="selection" width="44"/><el-table-column label="名称 / 备注" min-width="280"><template #default="{ row }"><button class="file-name-cell" @click="openFile(row)"><span :class="['file-icon',fileClass(row)]"><el-icon><component :is="icon(row)" /></el-icon></span><span class="file-name-text"><strong>{{ row.name }}</strong><small :title="row.remark">{{ row.remark || (row.kind === 'folder' ? '文件夹' : '暂无备注') }}</small></span></button></template></el-table-column><el-table-column label="大小" width="105"><template #default="{ row }">{{ row.kind === 'folder' ? '—' : size(row.size) }}</template></el-table-column><el-table-column label="上传者" prop="owner_name" width="110" /><el-table-column label="更新时间" width="155"><template #default="{ row }">{{ date(row.updated_at) }}</template></el-table-column><el-table-column label="状态" width="135"><template #default="{ row }"><span :class="['status-text',{ warning:row.scan_status !== 'clean' || row.publication !== 'published' || row.source_missing }]"><i></i>{{ statusText(row) }}</span></template></el-table-column><el-table-column label="操作" width="275" align="right"><template #default="{ row }"><el-button v-if="nav === 'trash' && row.can_manage" link type="primary" @click="restore(row)">恢复</el-button><template v-else-if="nav === 'review' && row.can_approve"><el-button link type="primary" :disabled="!row.can_download" @click="review(row,true)">通过</el-button><el-button link type="danger" @click="review(row,false)">退回</el-button></template><template v-else><el-button v-if="row.kind === 'folder' && !row.deleted" link type="primary" :loading="folderDownloadBusy === row.id" @click="download(row)">下载目录</el-button><el-button v-if="imagePreviewable(row) && canDownload(row)" link type="primary" @click="previewFile(row)">预览</el-button><el-button v-if="canDownload(row)" text circle :icon="Download" aria-label="下载文件" title="下载文件" @click="download(row)" /><el-button v-if="row.can_manage && !row.deleted" link type="danger" @click="trash(row)">移入回收站</el-button><el-dropdown trigger="click" @command="(c: string) => menuAction(c,row)"><el-button text circle :icon="MoreFilled" aria-label="文件操作" title="文件操作" /><template #dropdown><el-dropdown-menu><el-dropdown-item command="details" :icon="Document">查看详情</el-dropdown-item><el-dropdown-item v-if="row.kind === 'folder' && !row.deleted" command="download" :icon="Download">下载目录 ZIP</el-dropdown-item><el-dropdown-item v-if="imagePreviewable(row) && canDownload(row)" command="preview" :icon="Picture">图片预览</el-dropdown-item><el-dropdown-item command="link" :icon="Link">复制内部链接</el-dropdown-item><el-dropdown-item v-if="row.can_manage && !row.deleted" command="edit" :icon="EditPen">编辑名称和备注</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></template></el-table-column></el-table>
            <div v-else v-loading="loading" class="file-grid"><article v-for="f in resources" :key="f.id" class="file-card"><el-checkbox v-if="nav === 'files'" :model-value="selected.some(item => item.id === f.id)" :aria-label="'选择 ' + f.name" @update:model-value="toggleSelected(f,Boolean($event))"/><button class="grid-file-open" @click="openFile(f)"><span :class="['file-icon large',fileClass(f)]"><el-icon><component :is="icon(f)" /></el-icon></span><strong :title="f.name">{{ f.name }}</strong><p :title="f.remark">{{ f.remark || '暂无备注' }}</p></button><div><span>{{ f.kind === 'folder' ? '文件夹' : size(f.size) }}</span><span>{{ statusText(f) }}</span></div><div class="grid-file-actions"><el-button v-if="f.kind === 'folder' && !f.deleted" link type="primary" :loading="folderDownloadBusy === f.id" @click="download(f)">下载目录</el-button><el-button v-if="imagePreviewable(f) && canDownload(f)" link type="primary" @click="previewFile(f)">预览</el-button><el-button v-if="canDownload(f)" link type="primary" @click="download(f)">下载</el-button><el-button v-if="f.can_manage && !f.deleted" link type="danger" @click="trash(f)">移入回收站</el-button><el-button link @click="showDetails(f)">详情</el-button></div></article><el-empty v-if="!resources.length" :description="search ? '没有找到匹配的文件名或备注' : '暂无文件'" /></div>
            <div class="table-footer"><span><el-icon><Lock /></el-icon> {{ search ? '仅搜索当前空间内有权访问的文件名与备注' : '仅展示你有权访问的资源' }}</span><el-pagination v-model:current-page="page" :page-size="50" :total="total" layout="total, prev, pager, next" hide-on-single-page @current-change="loadFiles" /></div></section><div class="workspace-note"><el-icon><CircleCheck /></el-icon> {{ scanMode==='immediate'?'文件内容需通过安全检查后开放下载和预览。':'未检查文件允许访问并标注“未执行病毒检查”；已发现威胁或检查失败的文件仍被阻止。' }}</div>
        </template>
        <SiteSettings v-else-if="nav === 'settings' && isSuperAdmin" :api="api" :logo-url="logoURL" @updated="siteUpdated().catch(report)"/><template v-else-if="nav === 'users'"><div class="admin-summary"><span><el-icon><User /></el-icon>{{ users.length }} 位员工</span><span><el-icon><Collection /></el-icon>{{ departments.length }} 个部门</span><el-input v-model="userSearch" :prefix-icon="Search" clearable placeholder="搜索姓名、用户名或手机号" /></div><section class="files-panel"><el-table :data="visibleUsers" empty-text="暂无员工"><el-table-column label="员工" min-width="180"><template #default="{ row }"><div class="employee-cell"><span class="avatar small">{{ row.display_name.slice(0,1) }}</span><span>{{ row.display_name }}<small>{{ row.username }}</small></span></div></template></el-table-column><el-table-column label="手机号" prop="mobile" width="145" /><el-table-column label="部门" min-width="130"><template #default="{ row }">{{ row.dept_name || '未分配' }}</template></el-table-column><el-table-column label="角色" width="130"><template #default="{ row }">{{ roleNames[row.role] }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.enabled ? 'success' : 'info'" effect="plain">{{ row.enabled ? '正常' : '已停用' }}</el-tag></template></el-table-column><el-table-column label="个人配额" width="110"><template #default="{ row }">{{ size(row.quota_bytes) }}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" :disabled="!isSuperAdmin && row.role === 'admin'" @click="showUser(row)">编辑</el-button></template></el-table-column></el-table></section><section class="departments-section"><h3>公司部门</h3><div class="department-cards"><div v-for="d in departments" :key="d.id"><el-icon><Collection /></el-icon><span>{{ d.name }}<small>{{ departments.find(p => p.id === d.parent_id)?.name || '直属公司' }}</small></span></div><el-empty v-if="!departments.length" description="先创建部门，再为员工分配部门" :image-size="65" /></div></section></template>
        <template v-else-if="nav === 'imports'"><div class="import-intro"><div class="import-icon"><FolderOpened /></div><div><h2>让已有资料，进入统一管理</h2><p>保留源目录和原文件，仅登记文件索引。新登记的文件归公司空间，全员可见。</p><p class="subtle">重复扫描不重复入库，也不会覆盖已编辑的文件名与备注。</p></div><el-button type="primary" :icon="Refresh" :loading="importBusy || !!activeJob" :disabled="!system.legacy_configured" @click="startImport">{{ activeJob ? '正在扫描' : '扫描历史资料' }}</el-button></div><el-alert v-if="!system.legacy_configured" title="尚未配置文件存储和读取目录" description="请由超管在站点配置设置文件存储和读取目录，重启服务后扫描。" type="info" :closable="false" show-icon /><div v-else class="root-path"><el-icon><Folder /></el-icon><span>扫描目录</span><code>{{ system.legacy_root }}</code></div><el-alert v-if="!system.scanner_configured && system.virus_scan?.mode!=='off'" class="scanner-alert" title="安全扫描程序尚未配置" :description="system.virus_scan?.mode==='scheduled'?'定时模式允许未检查文件访问，但实际检查仍需配置 ClamAV 和病毒库。':'立即模式需检查通过后才能下载或预览，请配置 ClamAV 和病毒库。'" type="warning" :closable="false" show-icon /><el-alert v-if="system.virus_scan" class="scanner-alert" :title="system.virus_scan.mode==='off'?'病毒检查已关闭':system.virus_scan.mode==='scheduled'?'定时检查：'+system.virus_scan.start+'—'+system.virus_scan.end+'（北京时间）':'病毒检查：立即检查'" :description="system.virus_scan.mode==='immediate'?'未检查文件暂不能预览和下载。':'未检查文件允许预览和下载，标注“未执行病毒检查”；失败或发现威胁的文件继续阻止访问。'" type="info" :closable="false"/><div class="import-metrics"><div><span>待安全检查</span><strong>{{ system.pending_scans || 0 }}</strong></div><div><span>检查失败</span><strong>{{ system.failed_scans || 0 }}</strong></div><div><span>已阻止访问</span><strong>{{ system.infected_files || 0 }}</strong></div><el-button :disabled="!system.scanner_configured || system.virus_scan?.mode==='off'" :icon="Refresh" @click="retryScans">重试失败检查</el-button><el-button :icon="Refresh" @click="loadImports">刷新状态</el-button></div><div v-if="activeJob" class="active-import"><el-icon class="is-loading"><Loading /></el-icon><div>正在登记资料<small>{{ activeJob.current_path || '准备扫描…' }}</small></div><span>新增 {{ activeJob.added }} · 更新 {{ activeJob.updated }} · 跳过 {{ activeJob.skipped }}</span></div><section class="files-panel"><div class="section-title"><h3>扫描记录</h3><span>最近 20 次任务</span></div><el-table :data="jobs" empty-text="暂无扫描记录"><el-table-column label="开始时间" width="170"><template #default="{ row }">{{ date(row.created_at) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="row.status === 'completed' ? 'success' : row.status === 'running' ? 'primary' : 'warning'" effect="plain">{{ jobNames[row.status] }}</el-tag></template></el-table-column><el-table-column label="新增" prop="added" width="85" /><el-table-column label="更新" prop="updated" width="85" /><el-table-column label="跳过" prop="skipped" width="85" /><el-table-column label="异常" prop="errors" width="85" /><el-table-column label="说明" min-width="200"><template #default="{ row }">{{ row.error_note || (row.status === 'completed' ? '扫描完成，原文件保持不变' : '—') }}</template></el-table-column></el-table></section></template>
        <template v-else-if="nav === 'audit'"><section class="files-panel"><div class="section-title"><h3>最近操作</h3><el-button :icon="Refresh" @click="navigate('audit')">刷新</el-button></div><el-table :data="logs" empty-text="暂无操作记录"><el-table-column label="时间" width="170"><template #default="{ row }">{{ date(row.created_at) }}</template></el-table-column><el-table-column label="操作人" prop="user" width="120" /><el-table-column label="操作" min-width="170"><template #default="{ row }">{{ actionNames[row.action] || row.action }}</template></el-table-column><el-table-column label="对象编号" prop="target_id" min-width="220" show-overflow-tooltip /><el-table-column label="结果" prop="result" width="120" /></el-table></section></template>
        <footer class="app-footer"><a :href="copyrightURL" target="_blank" rel="noopener noreferrer">© {{ copyright }}</a><span>{{ companyShortName }} · 文件资源管理</span></footer>
      </div>
    </div>
  </div>

  <el-dialog v-model="folderOpen" title="新建文件夹" width="440px"><el-form label-position="top" @submit.prevent="createFolder"><el-form-item label="文件夹名称"><el-input v-model="folderForm.name" maxlength="255" placeholder="例如：项目资料" /></el-form-item><el-form-item label="备注"><el-input v-model="folderForm.remark" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="可填写用途、内容说明，支持搜索" /></el-form-item></el-form><template #footer><el-button @click="folderOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="createFolder">创建文件夹</el-button></template></el-dialog>
  <el-dialog v-model="editOpen" title="编辑名称和备注" width="500px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="editForm.name" maxlength="255" /></el-form-item><el-form-item label="备注"><el-input v-model="editForm.remark" type="textarea" :rows="5" maxlength="2000" show-word-limit placeholder="文件用途、关键词或内容说明" /></el-form-item></el-form><p class="subtle">名称和备注仅在系统内更新，不改动磁盘原文件。共享文件由普通员工修改后需重新审核。</p><template #footer><el-button @click="editOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEdit">保存</el-button></template></el-dialog>
  <el-dialog v-model="uploadOpen" title="上传文件" width="680px"><div class="upload-destination"><el-icon><FolderOpened /></el-icon> 上传至 {{ scope === 'personal' && browseOwner ? users.find(u => u.id === browseOwner)?.display_name + ' · ' : scope === 'department' && browseDept ? departments.find(d => d.id === browseDept)?.name + ' · ' : '' }}{{ titles[scope] }}<span v-for="a in ancestors" :key="a.id"> / {{ a.name }}</span></div><div class="dropzone" @dragover.prevent @drop="dropFiles" @click="fileInput?.click()"><el-icon :size="42"><UploadFilled /></el-icon><strong>点击选择文件，或拖放文件到这里</strong><span>支持图片、文档、视频、音频、软件及压缩包，单文件最大 10 GB</span></div><div class="folder-upload-choice"><el-button :icon="FolderOpened" @click="directoryInput?.click()">选择文件夹上传</el-button><span class="subtle">保留层级；每次最多 {{ folderLimits.max_files }} 个文件、{{ size(folderLimits.max_bytes) }}、{{ folderLimits.max_depth }} 层</span></div><input ref="directoryInput" type="file" webkitdirectory directory multiple hidden @change="addDirectory(($event.target as HTMLInputElement).files)"><input ref="fileInput" type="file" multiple hidden @change="addFiles(($event.target as HTMLInputElement).files)"><el-table v-if="selections.length" :data="selections" max-height="300"><el-table-column label="文件" min-width="180"><template #default="{ row }"><strong class="selection-name">{{ row.relativePath || row.file.name }}</strong><span class="subtle">{{ size(row.file.size) }}</span></template></el-table-column><el-table-column label="文件备注（可选）" min-width="230"><template #default="{ row }"><el-input v-model="row.remark" maxlength="2000" placeholder="添加备注，便于以后搜索" /></template></el-table-column><el-table-column width="45"><template #default="{ $index }"><el-button text circle :icon="Close" aria-label="移除待上传文件" @click="selections.splice($index,1)" /></template></el-table-column></el-table><p class="subtle">备注与文件遵守相同访问权限。共享文件可能需要管理员审核后发布。</p><template #footer><el-button @click="uploadOpen = false">取消</el-button><el-button type="primary" :disabled="!selections.length || uploadRunning" @click="beginUpload">上传 {{ selections.length || '' }} 个文件</el-button></template></el-dialog>
  <input ref="resumeInput" type="file" hidden @change="resumeSelected">
  <el-drawer v-model="uploadDrawer" title="文件传输" size="450px"><div v-if="uploadRunning" class="transfer-hint">文件正在上传，可关闭此面板继续浏览。<el-button link type="primary" @click="uploadAbort?.abort()">暂停当前上传</el-button></div><div v-for="t in tasks" :key="t.id" class="transfer-task"><div class="transfer-task-head"><el-icon><Document /></el-icon><strong>{{ t.name }}</strong><span>{{ size(t.size) }}</span></div><el-progress :percentage="t.progress || 0" :stroke-width="5" :status="t.progress === 100 && t.state?.includes('完成') ? 'success' : undefined" /><div class="transfer-state"><span>{{ t.state || '等待续传' }}</span><el-button v-if="!uploadRunning && !t.state?.includes('上传完成')" link type="primary" @click="selectResume(t)">选择原文件续传</el-button></div><p v-if="t.error" class="error-text">{{ t.error }}</p><el-button v-if="!uploadRunning && !t.state?.includes('上传完成')" link type="danger" @click="cancelTask(t)">取消任务</el-button></div><el-empty v-if="!tasks.length" description="暂无传输任务" /><p class="subtle">未完成任务保留 48 小时。重新打开后选择原文件，可继续上传。</p></el-drawer>
  <el-drawer v-model="detailOpen" title="资源详情" size="430px"><template v-if="detail"><div class="detail-heading"><span :class="['file-icon huge',fileClass(detail)]"><el-icon><component :is="icon(detail)" /></el-icon></span><h2>{{ detail.name }}</h2><el-tag effect="plain" :type="canDownload(detail) || detail.kind === 'folder' ? 'success' : 'warning'">{{ statusText(detail) }}</el-tag></div><dl class="detail-list"><dt>所属空间</dt><dd>{{ titles[detail.scope] }}</dd><dt>文件大小</dt><dd>{{ detail.kind === 'folder' ? '—' : size(detail.size) }}</dd><dt>上传者</dt><dd>{{ detail.owner_name }}</dd><dt>登记时间</dt><dd>{{ date(detail.created_at) }}</dd><dt>更新时间</dt><dd>{{ date(detail.updated_at) }}</dd><dt>来源</dt><dd>{{ detail.storage_kind === 'legacy' ? '历史资料登记' : '系统上传' }}</dd></dl><div class="remark-heading"><h3>文件备注</h3><el-button v-if="detail.can_manage && !detail.deleted" link type="primary" :icon="EditPen" @click="startEdit(detail)">编辑</el-button></div><div class="remark-content">{{ detail.remark || '暂无备注，添加用途和关键词让文件更容易找到。' }}</div><p v-if="detail.scan_note" class="scan-note"><el-icon><Warning /></el-icon>{{ detail.scan_note }}</p><div class="detail-actions"><el-button v-if="previewKind && canDownload(detail)" type="primary" @click="previewOpen = true">在线预览</el-button><el-button v-if="detail.kind === 'folder' && !detail.deleted" type="primary" :loading="folderDownloadBusy === detail.id" :icon="Download" @click="download(detail)">下载目录 ZIP</el-button><el-button v-if="canDownload(detail)" :icon="Download" @click="download(detail)">下载文件</el-button><el-button v-if="detail.deleted && detail.can_manage" type="primary" @click="restore(detail)">恢复文件</el-button><el-button :icon="Link" @click="copyLink(detail)">内部链接</el-button></div><div v-if="detail.can_manage && !detail.deleted" class="detail-bottom"><el-button text type="danger" :icon="Delete" @click="trash(detail)">移入回收站</el-button></div></template></el-drawer>
  <el-dialog v-model="previewOpen" :title="detail?.name || '文件预览'" width="85%" destroy-on-close><div class="preview-toolbar"><span>{{ previewKind === 'image' ? '图片在线预览' : '文件在线预览' }}</span><el-button v-if="detail && canDownload(detail)" :icon="Download" @click="download(detail)">下载原文件</el-button></div><div class="preview-container"><img v-if="previewKind === 'image'" :src="contentURL" :alt="detail?.name"><video v-else-if="previewKind === 'video'" :src="contentURL" controls preload="metadata"></video><audio v-else-if="previewKind === 'audio'" :src="contentURL" controls></audio><iframe v-else-if="previewKind === 'pdf'" :src="contentURL" title="PDF 文件预览"></iframe></div></el-dialog>
  <el-dialog v-model="userOpen" :title="editingUser ? '编辑员工' : '新增员工'" width="550px"><el-form label-position="top"><div class="form-two"><el-form-item label="用户名"><el-input v-model="userForm.username" placeholder="字母开头，3～32 位" autocomplete="off" /></el-form-item><el-form-item label="姓名"><el-input v-model="userForm.display_name" maxlength="100" /></el-form-item></div><el-form-item label="绑定手机号"><el-input v-model="userForm.mobile" maxlength="11" placeholder="用于手机号密码登录和短信验证，可选" /></el-form-item><el-form-item :label="editingUser ? '重置密码（留空不修改）' : '初始密码'"><el-input v-model="userForm.password" type="password" show-password autocomplete="new-password" placeholder="10～72 字节" /></el-form-item><div class="form-two"><el-form-item label="所属部门"><el-select v-model="userForm.dept_id"><el-option label="未分配" value="" /><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id" /></el-select></el-form-item><el-form-item label="角色"><el-select v-model="userForm.role"><el-option v-for="(name,key) in assignableRoles" :key="key" :value="key" :label="name" /></el-select></el-form-item></div><div class="form-two"><el-form-item label="个人空间配额（GB）"><el-input-number v-model="userForm.quota_gb" :min="1" :max="100000" /></el-form-item><el-form-item label="账号状态"><el-switch v-model="userForm.enabled" active-text="启用" inactive-text="停用" /></el-form-item></div><p class="subtle">保存账号调整后，该员工已有登录会话将失效。超管和维护管理员可查看、管理所有空间文件；员工仍按个人、部门权限隔离。</p></el-form><template #footer><el-button @click="userOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveUser">保存员工</el-button></template></el-dialog>
  <el-dialog v-model="deptOpen" title="新增部门" width="440px"><el-form label-position="top"><el-form-item label="部门名称"><el-input v-model="deptForm.name" maxlength="100" /></el-form-item><el-form-item label="上级部门"><el-select v-model="deptForm.parent_id"><el-option label="直属公司" value="" /><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id" /></el-select></el-form-item></el-form><p class="subtle">父子部门展示组织层级，不自动互相开放部门文件。</p><template #footer><el-button @click="deptOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="createDepartment">创建部门</el-button></template></el-dialog>
  <el-dialog v-model="passwordOpen" title="修改登录密码" width="440px"><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="passwordForm.old_password" type="password" show-password autocomplete="current-password" /></el-form-item><el-form-item label="新密码"><el-input v-model="passwordForm.new_password" type="password" show-password autocomplete="new-password" placeholder="10～72 字节" /></el-form-item><el-form-item label="确认新密码"><el-input v-model="passwordForm.confirm" type="password" show-password autocomplete="new-password" /></el-form-item></el-form><p class="subtle">修改后需重新登录，其他设备上的登录也将失效。</p><template #footer><el-button @click="passwordOpen = false">取消</el-button><el-button type="primary" :loading="saving" @click="changePassword">修改密码</el-button></template></el-dialog>
</template>
